/* Texture des reflets (une seule, partagée) : CubeUVReflectionMapping, comme la sortie de PMREMGenerator. */
function khepeshEnv() {
  if (KHEPESH.env) return KHEPESH.env;
  const img = new Image();
  const t = new THREE.Texture(img);
  t.mapping = THREE.CubeUVReflectionMapping; t.encoding = THREE.sRGBEncoding;
  t.magFilter = t.minFilter = THREE.NearestFilter; t.generateMipmaps = false; t.flipY = false;
  t.name = 'khepesh.env';
  img.onload = () => { t.needsUpdate = true; KHEPESH.envReady = true; };
  img.src = KHEPESH_ENV_SRC;
  return (KHEPESH.env = share(t));
}
